package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.CulpritVO;

@RequiredArgsConstructor
public class CulpritValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<CulpritVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param culprit
   * @return
   */
  public T culprit(CulpritVO culprit) {
    this.value = Optional.of(culprit);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param culprit
   * @return
   */
  public T culprit(Optional<CulpritVO> culprit) {
    this.value = culprit;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param culprit
   * @return
   */
  public T culprit(String culprit) {
    this.value = Optional.of(CulpritVO.from(culprit));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T culpritNull() {
    this.value = Optional.of(CulpritVO.nullValue());
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getCulprit() {
    return value.flatMap(CulpritVO::getCulprit);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<CulpritVO> getCulpritValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public CulpritVO readCulprit(final Optional<ObservedIssue> original,
      final ConstraintFailList fails) {
    return value
        .orElse(original.map(ObservedIssue::getCulpritValue).orElseGet(CulpritVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetCulprit() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetCulpritIfMatches(final String field) {
    if ("culprit".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
